const menu=document.querySelector('.menu'),nav=document.querySelector('#navigation');
function closeNav(){nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Open navigation');}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeNav));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){closeNav();menu.focus();}});
document.addEventListener('click',e=>{if(nav?.classList.contains('open')&&!nav.contains(e.target)&&!menu.contains(e.target))closeNav();});
window.matchMedia('(min-width: 1101px)').addEventListener('change',closeNav);
let selectedService='guarding';document.querySelectorAll('[data-service]').forEach(button=>button.addEventListener('click',()=>{selectedService=button.dataset.service;const item=serviceData[selectedService];document.querySelectorAll('[data-service]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('#service-title').textContent=item.title;document.querySelector('#service-tagline').textContent=item.tagline;document.querySelector('#service-description').textContent=item.description;document.querySelector('#service-number').textContent='SERVICE / '+item.number;document.querySelector('#service-icon').innerHTML=item.icon;if(window.matchMedia('(max-width: 800px)').matches)document.querySelector('#service-details').scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
document.querySelector('#service-enquire')?.addEventListener('click',()=>document.querySelector('#service-select').value=serviceData[selectedService].title);
document.querySelector('#enquiry-form')?.addEventListener('submit',e=>{e.preventDefault();document.querySelector('#enquiry-result').textContent='Preview complete. Nothing has been sent or saved. Please call, email or WhatsApp our team to enquire.';});
const documentDialog=document.querySelector('#document-dialog');document.querySelectorAll('[data-document]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.document;const doc=documentData[id];document.querySelector('#document-title').textContent=doc.title;document.querySelector('#document-detail').textContent=doc.description;const img=document.querySelector('#document-image');img.src=`/assets/documents/document-${id.padStart(2,'0')}.webp?v=7`;img.alt=doc.title+' — watermarked, redacted copy';document.querySelector('#document-fullsize').href=img.src;documentDialog.showModal();documentDialog.scrollTop=0;}));
documentDialog?.querySelector('.dialog-close').addEventListener('click',()=>documentDialog.close());documentDialog?.addEventListener('click',e=>{if(e.target===documentDialog){const r=documentDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)documentDialog.close();}});
const filters=[...document.querySelectorAll('[data-filter]')],documents=[...document.querySelectorAll('.document-card')];
function filterDocuments(value){let count=0;documents.forEach((card,i)=>{const show=value==='all'||(value==='featured'?i<3:card.dataset.category===value);card.hidden=!show;if(show)count++;});filters.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.filter===value)));document.querySelector('#gallery-count').textContent=`Showing ${count} of ${documents.length} documents`;document.querySelector('#view-all-documents').hidden=value==='all';}
if(documents.length){filters.forEach(button=>button.addEventListener('click',()=>filterDocuments(button.dataset.filter)));document.querySelector('#view-all-documents').addEventListener('click',()=>filterDocuments('all'));const category=location.hash.slice(1);filterDocuments(['training','accommodation','licences','registrations'].includes(category)?category:'featured');}
